  "su2dwh": "ایک صاف شدہ پیاد میں کوئی دشمن کا پیادہ نہیں ہے جو پروموشن اسکوائر تک اپنے راستے کو روکتا ہے یا کنٹرول نہیں کرتا ہے۔ \"پچھی ہوئے پیادوں کو دھکیل دیا جانا چاہیے۔\" پیادے سے محفوظ ایک صاف پاین بہت پائیدار ہے۔ ایک بیرونی پاس کا پیادہ (بادشاہ سے دور) دشمن کے بادشاہ کو گھسیٹتا ہے تاکہ آپ کا بادشاہ دوسرے پروں پر پیادوں کو لے سکے۔ ایک دشمن کو بلاک کریں جس کے سامنے براہ راست ایک ٹکڑا تھا (ایک نائٹ بہترین ہے)۔",
