  "15zappz": "پاون چینز: بیس پر حملہ کریں",
  "11dasr2": "ایک ڈائیگنل پیادہ سلسلہ (مثال کے طور پر وائٹ کی d4-e5 فرانسیسی دفاع میں) سر پر مضبوط اور بیس پر کمزور ہے۔ زنجیر کی بنیاد پر حملہ کریں (بلیک کے لیے،...c5 مارنا d4پھر،...f6 مارنا e5) عام طور پر آپ کے پیادے کی زنجیر کی طرف کی طرف کھیلتے ہیں: d4-e5 زنجیر کنگ سائیڈ کی طرف اشارہ کرتی ہے، اس لیے بادشاہ کے کنارے پر سفید فام حملے اور ملکہ پر سیاہ فام جوابی حملوں کی طرف اشارہ کرتی ہے۔",
