  "1wohxd2": "ٹکڑوں کا تبادلہ کب کریں",
  "cmvxf3": "جب مواد میں آگے بڑھیں: آسانی سے جیت جانے والے اینڈگیم تک پہنچنے کے لیے ٹکڑوں کا تبادلہ (پیاد نہیں)۔ جب پیچھے: تبادلے سے گریز کریں، پیادے رکھیں اور کاؤنٹر پلے تلاش کریں۔ جب درد کیا جاتا ہے: اپنے آپ کو آزاد کرنے کے لیے کچھ ٹکڑوں کا تبادلہ کریں۔ مخالف کے حملہ آور ٹکڑوں کو تبدیل کریں اور اپنے فعال رکھ دیں۔ مخالف کے اچھے بشپ کے لیے اپنے برے بشپ کو جوڑنا ایک فائدہ ہے۔",
  "ht9l4o": "پروفلیکسس: مخالف کیا چاہتا ہے؟",
