  "1qopdgf": "پیادے کا مرکز اور اسے کمزور کر رہا ہے",
  "xbbabg": "ایک پیادہ مرکز (پچھیں e4 اور d4) جگہ دیتا ہے اور دشمن کے ٹکڑوں کو محدود کرتا ہے۔ ہائپر ماڈرن پلے مخالف کو ایک مرکز بنانے دیتا ہے اور پھر اسے ٹکڑوں اور پیادوں سے حملہ کرتا ہے (...c5, ...e5, ...f6) ایک بند مرکز (پان بند) کے ساتھ، کھیل پروں پر حملہ کرنے کی طرف بڑھ جاتا ہے ؛ ایک کھلے مرکز کے ساتھ، فوری ترقی اور بادشاہ کی حفاظت زیادہ اہمیت رکھتی ہے۔",
  "rdaiwm": "اوپوسی سائیڈ کالنگ: پیادوں پر تیرنے کے لیے دشمن بادشاہ کی طرف دھاوا بولیں ؛ تیز رفتار پہلو عام طور پر جیت جاتا ہے۔ ایک جیسے کنارے کالنگ: اپنے ہی بادشاہ کے سامنے پیادوں کو دھکیلنے کے بجائے ٹکڑوں (کوئین، نائٹ اور بشپ کو بادشاہ کی طرف) سے حملہ کرنا۔ نیم بادشاہ اب بھی بیچ میں ہے: پیادوں کے ساتھ مرکز کھولتا ہے، یہاں تک کہ قربانی کی قیمت پر بھی۔ آپ کو بادشاہ کے قریب محافظوں سے زیادہ حملہ آوروں کی ضرورت ہے۔",
  "lt1w6h": "اختتامی کھیل میں بادشاہ ایک سرگرم مہرہ ہے",
