  "1fc6m76": "حزب اختلاف اور کلیدی چوکوں (بنگ  پیادہ بمقابلہ بادشاہ)",
  "156bncz": "حزب اختلاف: دو بادشاہ ایک دوسرے کا سامنا کرتے ہیں ؛ ایک دوسرے کو الگ الگ کرنے کی طرف سے \"اپوزیشن\" نہیں ہے اور دوسرے بادشاہ کو واپس دھکیل سکتا ہے۔ بی سے جی فائلوں پر پیادے کے ساتھ، اگر اس کا بادشاہ کسی کلیدی مربع تک پہنچتا ہے تو مضبوط پہلو جیت جاتا ہے۔ ایک پیادہ ابھی تک بیچ سے آگے نہیں ہے (مثال کے طور پر e4) میں کلیدی مربع d6، e6، f6 ؛ پانچویں رینک (e5) پر ایک پیادے بھی d7، e7، f7 ہے۔ اصول: بادشاہ پیادے سے آگے جاتا ہے ؛ پیادے کو زیادہ جلد نہیں دھکیلتا۔ اگر دفاعی بادشاہ کونے تک پہنچتا ہے تو یہ عام طور پر ڈرا ہوتا ہے۔",
  "2oijvr": "ایک مربع کی تصویر جس میں ایک پاس شدہ پیاد سے اس کے پروموشن اسکوائر تک چلنے والے اطراف کے ساتھ چلتی ہیں۔ اگر دشمن کا بادشاہ اس چوک کے اندر قدم رکھ سکتا ہے (جس کے اقدام کی گنتی کرتے ہوئے یہ ہے)، تو یہ پیادے کو پکڑ لیتا ہے ؛ اگر نہیں تو، پیادے کو فروغ دیتا ہے۔ اس کے ابتدائی رینک پر پیادہ اس طرح شمار ہوتا ہے جیسے پہلے سے ہی اگلے درجے پر، کیونکہ یہ دو مربع منتقل کر سکتا ہے۔",
  "1auk0a6": "لوسینا پوزیشن: \"ایک پل بنانا\"",
  "16xqsgv": "ساتویں رینک بمقابلہ روک پر روک، پروموشن اسکوائر پر مضبوط بادشاہ اور دشمن کے بادشاہ کے ساتھ ایک فائل سے منقطع ہو گئے۔ جیتنے کا طریقہ: اپنے روک کو چوتھے درجے پر لانے (آپ کی طرف سے شمار کیا گیا)، اپنے بادشاہ کو پروموشن اسکوائر سے باہر جانے دیں ؛ جب دشمن فائل کے ساتھ چیک کرتا ہے، تو آپ کا بادشاہ آپ کے روک کی طرف بڑھتا ہے، اور پھر آپ کا روک چوتھے درجے پر چیک کو روکتا ہے۔ یہ روک اینڈگیمز میں سب سے اہم جیتنے کی پوزیشن ہے۔",
  "dtj3ij": "فلیڈور پوزیشن: روکی دفاع",
  "1pfu08h": "پکے بمقابلہ روک، پیادے کے سامنے دفاعی بادشاہ کے ساتھ۔ اپنے کردار کو اپنی طرف سے تیسرے درجے پر رکھیں (بلیک کے لیے چھٹا رینک) تاکہ دشمن کا بادشاہ آگے نہیں بڑھ سکتا۔ جب پیاد اس رینک تک جاتا ہے، تو آپ کا روک فوری طور پر مخالف کے بیک رینک پر جاتا ہے اور پیچھے سے چیک کرتا ہے۔ اس سیٹ اپ ڈرا کو پکڑنا۔",
  "1f23jys": "روک اینڈگیم کے اصول",
  "lltdpa": "پیچھے روکوں کو پاس کیا گیا (آپ انہیں دھکیلنے کے لیے اپنا ہے، مخالف انہیں روکنے کے لیے)، کیونکہ پیادے کی پیش قدمی کے ساتھ زیادہ چوکے ملتے ہیں۔ ایک فعال روک پیاد سے زیادہ اہمیت رکھتا ہے: صرف پیادے کی حفاظت کرنے والا ایک غیر فعال روک اکثر کھو دیتا ہے۔ اپنے روک کا استعمال اپنے بادشاہ کو رینک یا فائل کے ساتھ کاٹ کر کریں۔ بہت سے روک اینڈگیمز ایک پیادہ نیچے اب بھی کھینچے جاتے ہیں۔",
  "piimbn": "غلط رنگ کا بشپ جس میں اے-یا ایچ-پاون تھا۔",
  "o1712e": "بشپ -یا ایچ-) پیادہ نہیں جیت سکتا اگر بشپ پروموشن اسکوائر کو کنٹرول نہیں کرتا ہے (کوارے کا رنگ مختلف ہے) اور دفاعی بادشاہ کونے تک پہنچ گیا ہے: نتیجہ ڈرا ہے۔ ایک محافظ جو مواد میں پیچھے ہے اس کا مقصد اس کا مقصد رکھنا چاہیے۔ مضبوط فریق کو دوسرے پیادے رکھنا چاہیے یا دشمن کے بادشاہ کو کونے سے باہر رکھنا چاہیے۔",
  "6tjt9l": "مخالف رنگ کے بشپ اینڈگیمز",
  "16gtq2f": "ہر فریق کا صرف ایک بشپ ہوتا ہے، مخالف رنگوں پر: ڈرا ہونے کا بہت امکان ہے، یہاں تک کہ پیاد یا دو نیچے، کیونکہ دشمن کے بشپ کے چوکوں پر بادشاہ یا بشپ کے ساتھ محافظ ناکہ بندی نہیں پہنچ سکتا۔ دوسرے ٹکڑوں کو شامل کرنے کے ساتھ (خون، روک) الٹا ہولڈز: حملہ آور مضبوط ہے، کیونکہ دفاعی بشپ دوسرے رنگ کا احاطہ نہیں کر سکتا۔",
  "1qfz8hg": "تعطل: جیتنے پر اس سے گریز کریں، ہارنے پر اسے تلاش کریں",
  "16dryd": "تعطل یہ ہے کہ حرکت کرنے والی طرف قابو میں نہیں ہے لیکن اس کا کوئی قانونی اقدام نہیں ہے: کھیل ڈرا ہو جاتا ہے۔ جیتنے والی ٹیم (خاص طور پر ملکہ کے ساتھ) کو ہمیشہ یہ چیک کرنا چاہیے کہ دشمن بادشاہ کے پاس اب بھی ایک مربع ہے۔ ہارنے والی ٹیم کو تعطل پیدا کرنے کی کوشش کرنی چاہیے: بادشاہ کو کونے میں رکھیں اور باقی ٹکڑوں کو قربان کریں۔",
  "56kb31": "ساتویں نمبر پر ملکہ بمقابلہ پیادہ",
