  "sntmog": "زوگانگ اور مثلث",
  "1el4osz": "زوگاژوانگ: حرکت کرنے والی طرف کو اپنی پوزیشن کو مزید خراب کرنا چاہیے۔ یہ پیادے اینڈگیمز میں عام ہے۔ مثلث: بادشاہ \"تیپ کو ختم کرنے\" کے لیے ایک مثلث میں تین حرکت کرتا ہے، مخالف کی طرف واپس جاتے ہوئے اور انہیں زوگاژوانگ میں ڈال دیتا ہے۔ اسپیئر پیادے کا اقدام ریزرو میں رکھنا ٹیمپو جنگ جیتنے کا ایک اور طریقہ ہے۔",
