  "1kmdptg": "اوپن اور بند پوزیشنیں",
  "1xf8nfy": "کھلی پوزیشنیں (پیو سنٹرل پیادے، بہت سی کھلی فائلیں): ترقی کی رفتار، بادشاہ کی حفاظت اور بشپ جوڑی بہت اہم ہے، اور حکمت عملی اکثر ظاہر ہوتی ہیں۔ بند پوزیشنیں (لاکڈ پیادے کی زنجیروں): شورویروں سے بہتر ہیں، کھیل سست ہے، اور منصوبہ یہ ہے کہ پروں پروں پروں اور ٹکڑوں کو اچھے چوکوں تک دھکیل دیا جائے۔ منصوبے کا انتخاب کرنے سے پہلے، فیصلہ کریں کہ مرکز کھلا ہے یا بند ہے۔",
